import { _decorator, Component, Node, Mesh, Material, MeshRenderer, Vec3, Quat } from 'cc';
import { EDITOR_NOT_IN_PREVIEW } from 'cc/env';
const { ccclass, property, executeInEditMode } = _decorator;

const DEBUG_CONTAINER_NAME = '__BuildingObstacleDebug__';
const LINE_THICKNESS = 0.08;
const LINE_Y_OFFSET  = 0.03;

/**
 * 건물(Wall/Tower 등)이 서 있는 자리를 캐릭터/몬스터가 통과하지 못하게 막는 "키프아웃"
 * 영역. MapBounds(맵 전체를 감싸는 "이 안에만 있어야 한다" 다각형)와 반대 개념이지만
 * 구현 원리는 동일하다 — 물리엔진 콜라이더를 쓰지 않고, Player/Monster의 이동 계산에서
 * 다음 위치가 이 영역 안이면 그 축 이동만 취소하는 방식(맵 경계를 미끄러지듯 못 나가는
 * 것과 같은 방식으로, 벽을 미끄러지듯 못 뚫고 지나간다).
 *
 * 노드의 Y축 회전(yaw)만큼 기울어진 직사각형으로 판정한다 — Wall이 45°/135° 등으로
 * 비스듬히 배치되므로 원이 아니라 회전된 사각형이어야 벽 두께에 맞게 정확히 막힌다.
 *
 * BuildingTrigger가 소켓 완료로 건물이 "등장"하는 바로 그 순간 activate()를 호출해야
 * 실제로 막기 시작한다 — 그 전(트리거 전 숨겨진 상태)에는 항상 통과 가능.
 */
@ccclass('BuildingObstacle')
@executeInEditMode
export class BuildingObstacle extends Component {
    /** 현재 씬에서 활성화된 모든 건물 장애물 — Player/Monster가 매 프레임 순회하며 충돌 판정한다 */
    static all: BuildingObstacle[] = [];

    @property({ displayName: '가로 폭(X, m)', tooltip: '프리팹 기준(스케일 1일 때) 로컬 X축 방향 폭 — 실제 판정 크기는 activate() 시점에 그 인스턴스의 실제 worldScale.x를 곱해서 계산되므로, 씬에서 개별 배치본을 다르게 스케일해도 그만큼 따라간다' })
    width: number = 1.5;

    @property({ displayName: '세로 폭(Z, m)', tooltip: '프리팹 기준(스케일 1일 때) 로컬 Z축 방향 폭 — 실제 판정 크기는 activate() 시점에 그 인스턴스의 실제 worldScale.z를 곱해서 계산되므로, 씬에서 개별 배치본을 다르게 스케일해도 그만큼 따라간다' })
    depth: number = 1.5;

    @property({ displayName: '여유 마진(m)', tooltip: '캐릭터가 벽 메쉬에 파묻히지 않도록 실제 크기보다 살짝 넓게 막을 여유분(캐릭터 반경 정도)' })
    margin: number = 0.3;

    @property({ displayName: '외곽선 표시', tooltip: '체크하면 씬 뷰(편집 중)에서만 판정 영역을 그려 확인할 수 있습니다. Play/빌드 중에는 항상 숨겨집니다.' })
    get showDebugOutline(): boolean { return this._showDebugOutline; }
    set showDebugOutline(v: boolean) {
        this._showDebugOutline = v;
        this._debugContainer && (this._debugContainer.active = v && EDITOR_NOT_IN_PREVIEW);
    }
    private _showDebugOutline = true;

    @property(Mesh)     segmentMesh:     Mesh     | null = null;
    @property(Material) segmentMaterial: Material | null = null;

    private _debugContainer: Node | null = null;
    private _segNodes: Node[] = [];
    /** BuildingTrigger가 건설(등장) 시점에 true로 켜주기 전까지는 막지 않는다 */
    private _active = false;

    // ── 판정용 캐시 — 건물은 activate() 이후 절대 움직이거나 회전하지 않으므로,
    // blocks() 호출마다 매번 위치/삼각함수를 다시 구하지 않고 activate() 시점에 한 번만
    // 계산해둔다. Player+최대 40마리 몬스터가 매 프레임 모든 건물에 대해 이 함수를
    // 부르는 핫패스라, 여기서 아낀 게 그대로 체감 성능으로 이어진다. */
    private _cachedX = 0;
    private _cachedZ = 0;
    private _cachedCos = 1;
    private _cachedSin = 0;
    private _cachedHalfW = 0;
    private _cachedHalfD = 0;
    /** 바깥 경계원(half-diagonal+margin)의 제곱 — 이 밖이면 회전 변환까지 갈 것도 없이 즉시 통과 */
    private _cachedBoundRadiusSq = 0;

    /** 건설 완료(등장) 시점에 BuildingTrigger가 호출 — 이 순간부터 통과 불가.
     * 이 시점의 실제 worldPosition/worldRotation/worldScale을 전부 읽어서 캐싱하므로,
     * 프리팹 기본값이 아니라 "씬에 배치된 이 인스턴스가 실제로 지금 어떤 모습인지"를
     * 그대로 반영한다 — 개별 배치본을 씬에서 다르게 돌리거나 늘려도 그만큼 따라간다. */
    activate() {
        const p = this.node.worldPosition;
        const s = this.node.worldScale;
        const angle = -this._yaw(this.node.worldRotation);
        this._cachedX = p.x;
        this._cachedZ = p.z;
        this._cachedCos = Math.cos(angle);
        this._cachedSin = Math.sin(angle);
        this._cachedHalfW = (this.width  * Math.abs(s.x)) / 2 + this.margin;
        this._cachedHalfD = (this.depth  * Math.abs(s.z)) / 2 + this.margin;
        const r = Math.hypot(this._cachedHalfW, this._cachedHalfD);
        this._cachedBoundRadiusSq = r * r;
        this._active = true;
    }

    onEnable() { BuildingObstacle.all.push(this); }
    onDisable() {
        const i = BuildingObstacle.all.indexOf(this);
        if (i >= 0) BuildingObstacle.all.splice(i, 1);
    }

    /** 이 장애물이 월드 (x,z) 지점을 막고 있는지 (활성화 전이면 항상 통과 가능) */
    blocks(x: number, z: number): boolean {
        if (!this._active) return false;
        const dx = x - this._cachedX, dz = z - this._cachedZ;

        // 조기 컷: 건물 중심에서 (여유분 포함) 최대 반경 밖이면 회전 변환 계산 없이 바로 통과.
        // 건물 수가 늘어나도(맵이 커져도) 대부분의 호출이 이 한 줄에서 끝나게 하기 위함.
        if (dx * dx + dz * dz > this._cachedBoundRadiusSq) return false;

        const lx = dx * this._cachedCos - dz * this._cachedSin;
        const lz = dx * this._cachedSin + dz * this._cachedCos;
        return Math.abs(lx) <= this._cachedHalfW && Math.abs(lz) <= this._cachedHalfD;
    }

    /** 등록된 장애물 중 하나라도 (x,z)를 막고 있으면 true */
    static isBlocked(x: number, z: number): boolean {
        for (const o of BuildingObstacle.all) {
            if (o.blocks(x, z)) return true;
        }
        return false;
    }

    private _yaw(q: Quat): number {
        // 건물은 지면에 눕지 않는다고 가정하고 Y축 회전만 추출
        return Math.atan2(2 * (q.w * q.y + q.x * q.z), 1 - 2 * (q.y * q.y + q.z * q.z));
    }

    // ── 에디터 디버그 시각화 (MapBounds와 동일한 패턴) ──────────────────────
    onLoad() {
        if (!EDITOR_NOT_IN_PREVIEW) this._ensureContainer().active = false;
    }

    update() {
        if (!EDITOR_NOT_IN_PREVIEW) return;
        if (this._showDebugOutline) this._redrawDebug();
    }

    private _ensureContainer(): Node {
        if (this._debugContainer && this._debugContainer.isValid) return this._debugContainer;
        let c = this.node.getChildByName(DEBUG_CONTAINER_NAME);
        if (!c) { c = new Node(DEBUG_CONTAINER_NAME); this.node.addChild(c); }
        c.setPosition(0, 0, 0);
        c.setRotationFromEuler(0, 0, 0);
        c.setScale(1, 1, 1);
        this._debugContainer = c;
        this._segNodes = c.children.slice();
        return c;
    }

    private _ensureSegCount(count: number) {
        const container = this._ensureContainer();
        while (this._segNodes.length < count) {
            const seg = new Node(`seg_${this._segNodes.length}`);
            container.addChild(seg);
            const mr = seg.addComponent(MeshRenderer);
            if (this.segmentMesh)     mr.mesh = this.segmentMesh;
            if (this.segmentMaterial) mr.setMaterial(this.segmentMaterial, 0);
            this._segNodes.push(seg);
        }
        for (let i = count; i < this._segNodes.length; i++) this._segNodes[i].active = false;
        for (let i = 0; i < count; i++) this._segNodes[i].active = true;
    }

    private _redrawDebug() {
        if (!this.segmentMesh || !this.segmentMaterial) {
            if (this._debugContainer) this._debugContainer.active = false;
            return;
        }
        this._debugContainer && (this._debugContainer.active = true);
        this._ensureSegCount(4);

        const p = this.node.worldPosition;
        const s = this.node.worldScale;
        const angle = this._yaw(this.node.worldRotation);
        const cos = Math.cos(angle), sin = Math.sin(angle);
        const hw = (this.width * Math.abs(s.x)) / 2 + this.margin;
        const hd = (this.depth * Math.abs(s.z)) / 2 + this.margin;
        const local: [number, number][] = [[-hw, -hd], [hw, -hd], [hw, hd], [-hw, hd]];
        const world = local.map(([lx, lz]) => ({
            x: p.x + lx * cos - lz * sin,
            z: p.z + lx * sin + lz * cos,
        }));
        for (let i = 0; i < 4; i++) {
            const a = world[i], b = world[(i + 1) % 4];
            this._placeSegment(this._segNodes[i], a.x, a.z, b.x, b.z);
        }
    }

    /** a→b 구간을 잇는 얇은 평면 하나를 배치 (MapBounds._placeSegment와 동일 원리) */
    private _placeSegment(seg: Node, ax: number, az: number, bx: number, bz: number) {
        const dx = bx - ax, dz = bz - az;
        const len = Math.hypot(dx, dz) || 0.0001;

        seg.setWorldPosition((ax + bx) / 2, LINE_Y_OFFSET, (az + bz) / 2);

        const rollRad = Math.atan2(-dz, dx);
        const qRoll  = Quat.fromAxisAngle(new Quat(), Vec3.UNIT_Z, rollRad);
        const qTilt  = Quat.fromAxisAngle(new Quat(), Vec3.UNIT_X, -Math.PI / 2);
        const qFinal = new Quat();
        Quat.multiply(qFinal, qTilt, qRoll);
        seg.setRotation(qFinal);

        seg.setScale(len / 2, LINE_THICKNESS / 2, 1);
    }
}
